#!/usr/bin/env python3
"""
Script da eseguire SUL SERVER dopo esserti connesso con: bash ssh-pf.bash

Copia questo script sul server e eseguilo:
1. bash ssh-pf.bash
2. python3 upload_to_server.py
"""
import base64
import os

# Contenuto base64 di epg_importer.py
EPG_B64 = """"""

# Contenuto base64 di check_and_cleanup_duplicates.py  
CLEANUP_B64 = """"""

def main():
    print("📤 Caricamento file...")
    
    # Crea directory
    os.makedirs("/home/u914016995/epg_importer_fr/scripts", exist_ok=True)
    
    # Scrivi epg_importer.py
    with open("/home/u914016995/epg_importer_fr/epg_importer.py", "wb") as f:
        f.write(base64.b64decode(EPG_B64))
    os.chmod("/home/u914016995/epg_importer_fr/epg_importer.py", 0o755)
    print("✅ epg_importer.py caricato")
    
    # Scrivi check_and_cleanup_duplicates.py
    with open("/home/u914016995/epg_importer_fr/scripts/check_and_cleanup_duplicates.py", "wb") as f:
        f.write(base64.b64decode(CLEANUP_B64))
    os.chmod("/home/u914016995/epg_importer_fr/scripts/check_and_cleanup_duplicates.py", 0o755)
    print("✅ check_and_cleanup_duplicates.py caricato")
    
    # Verifica
    epg_size = os.path.getsize("/home/u914016995/epg_importer_fr/epg_importer.py")
    cleanup_size = os.path.getsize("/home/u914016995/epg_importer_fr/scripts/check_and_cleanup_duplicates.py")
    print(f"\n✅ Upload completato!")
    print(f"   epg_importer.py: {epg_size} bytes")
    print(f"   check_and_cleanup_duplicates.py: {cleanup_size} bytes")

if __name__ == "__main__":
    main()
